export const FEN={start:"rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1",empty:"8/8/8/8/8/8/8/8"};export class Position{constructor(e=FEN.empty){this.squares=new Array(64).fill(null),this.setFen(e)}setFen(e=FEN.empty){const t=e.replace(/^\s*/,"").replace(/\s*$/,"").split(/\/|\s/);for(let e=0;e<8;e++){const s=t[7-e].replace(/\d/g,(e=>{const t=parseInt(e);let s="";for(let e=0;e<t;e++)s+="-";return s}));for(let t=0;t<8;t++){const r=s.substring(t,t+1);let o=null;"-"!==r&&(o=r.toUpperCase()===r?`w${r.toLowerCase()}`:`b${r}`),this.squares[8*e+t]=o}}}getFen(){let e=new Array(8).fill("");for(let t=0;t<8;t++){let s=0;for(let r=0;r<8;r++){const o=this.squares[8*t+r];if(o){s>0&&(e[7-t]+=s,s=0);const r=o.substring(0,1),n=o.substring(1,2);e[7-t]+="w"===r?n.toUpperCase():n}else s++}s>0&&(e[7-t]+=s,s=0)}return e.join("/")}getPieces(e,t,s=["k","q","r","b","n","p"]){const r=[],o=(e,t)=>s.indexOf(e.name)-s.indexOf(t.name);for(let s=0;s<64;s++){const o=this.squares[s];if(o){const n=o.charAt(1),i=o.charAt(0),a=Position.indexToSquare(s);if(t&&t!==n||e&&e!==i)continue;r.push({name:n,type:n,color:i,position:a,square:a})}}return s&&r.sort(o),r}movePiece(e,t){this.squares[Position.squareToIndex(e)]&&(this.squares[Position.squareToIndex(t)]=this.squares[Position.squareToIndex(e)],this.squares[Position.squareToIndex(e)]=null)}setPiece(e,t){this.squares[Position.squareToIndex(e)]=t}getPiece(e){return this.squares[Position.squareToIndex(e)]}static squareToIndex(e){const t=Position.squareToCoordinates(e);return t[0]+8*t[1]}static indexToSquare(e){return this.coordinatesToSquare([Math.floor(e%8),e/8])}static squareToCoordinates(e){return[e.charCodeAt(0)-97,e.charCodeAt(1)-49]}static coordinatesToSquare(e){return String.fromCharCode(e[0]+97)+String.fromCharCode(e[1]+49)}toString(){return this.getFen()}clone(){const e=Object.create(Position.prototype);return e.squares=this.squares.slice(0),e}}